"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** What `suggest` may return: the words to add after the text, or nothing. A promise is fine. */
export type GhostCompletion = string | null | undefined;

/** Props for a field with a ghost suggestion. Pass `value` to control the text, or `defaultValue` to let it hold its own. */
export type GhostSuggestionProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "defaultValue" | "onChange"> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Returns only the words to add, not the whole text. A rejected promise shows a short line under the field. */
  suggest: (text: string) => GhostCompletion | Promise<GhostCompletion>;
  /** Whether suggestions are on. Pass it to control the toggle, or `defaultEnabled` to let it hold its own. */
  enabled?: boolean;
  defaultEnabled?: boolean;
  onEnabledChange?: (enabled: boolean) => void;
  onAccept?: (completion: string) => void;
  /** Names the field for screen readers. */
  label: string;
  placeholder?: string;
};

const EASE_OUT = [0.165, 0.84, 0.44, 1] as const;
const APPEAR: Transition = { duration: 0.15, ease: EASE_OUT };
// The tint behind accepted words fades away; nothing travels, so reduced motion keeps it.
const SETTLE: Transition = { duration: 0.5, ease: EASE_OUT };

function SparkGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-3.5 shrink-0">
      <path d="M8 1 9.8 6.2 15 8 9.8 9.8 8 15 6.2 9.8 1 8l5.2-1.8L8 1Z" />
    </svg>
  );
}

// One size for the field and the layer behind it, or the ghost lands on the typed words.
// 1rem is the size a text field needs on a phone, so no host style has cause to change it.
const TEXT = "px-3 py-2.5 text-base leading-6";

/**
 * A text field that offers a greyed completion after the caret as the person
 * types. Tab accepts it and the new words settle with a brief tint, Escape
 * dismisses it, and typing on replaces it. A toggle turns suggestions off.
 */
export function GhostSuggestion({
  value,
  defaultValue = "",
  onValueChange,
  suggest,
  enabled,
  defaultEnabled = true,
  onEnabledChange,
  onAccept,
  label,
  placeholder,
  className,
  ...divProps
}: GhostSuggestionProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const [ownEnabled, setOwnEnabled] = useState(defaultEnabled);
  const text = value ?? ownValue;
  const on = enabled ?? ownEnabled;
  // The completion remembers the text it was made for, so a stale one never shows.
  const [offer, setOffer] = useState<{ for: string; completion: string } | null>(null);
  const [failedFor, setFailedFor] = useState<string | null>(null);
  const [dismissedFor, setDismissedFor] = useState<string | null>(null);
  const [atEnd, setAtEnd] = useState(true);
  const [settle, setSettle] = useState<{ id: number; before: string; added: string } | null>(null);
  const input = useRef<HTMLInputElement>(null);
  const suggestRef = useRef(suggest);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    suggestRef.current = suggest;
  }, [suggest]);

  useEffect(() => {
    if (!on || text.length === 0) return;
    let current = true;
    // Wrapped so a function that throws lands in the same place as a promise that rejects.
    new Promise<GhostCompletion>((resolve) => resolve(suggestRef.current(text)))
      .then((completion) => {
        if (!current) return;
        setFailedFor(null);
        setOffer(completion ? { for: text, completion } : null);
      })
      .catch(() => {
        if (current) setFailedFor(text);
      });
    return () => {
      current = false;
    };
  }, [on, text]);

  const ghost = on && atEnd && offer?.for === text && dismissedFor !== text ? offer.completion : "";
  const failed = on && failedFor === text;

  const change = (next: string) => {
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const accept = () => {
    if (!ghost) return;
    setSettle({ id: (settle?.id ?? 0) + 1, before: text, added: ghost });
    change(text + ghost);
    onAccept?.(ghost);
    input.current?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    // With no suggestion on screen, Tab and Escape keep their usual jobs.
    if (!ghost) return;
    if (event.key === "Tab" && !event.shiftKey) {
      event.preventDefault();
      accept();
    } else if (event.key === "Escape") {
      event.preventDefault();
      setDismissedFor(text);
    }
  };

  const readCaret = () => {
    const node = input.current;
    // A scrolled field no longer lines up with the layer behind it, so the ghost waits.
    if (node) setAtEnd(node.selectionStart === node.value.length && node.selectionEnd === node.value.length && node.scrollLeft === 0);
  };

  const toggle = () => {
    if (enabled === undefined) setOwnEnabled(!on);
    onEnabledChange?.(!on);
  };

  return (
    <div {...divProps} className={cn("flex w-full flex-col gap-1", className)}>
      <div className="relative rounded-xl border border-border bg-card focus-within:ring-2 focus-within:ring-ring">
        {/* Same box and type as the field, behind it: an unseen copy of the text pushes the ghost to the caret. */}
        <div aria-hidden="true" className={cn(TEXT, "pointer-events-none absolute inset-0 overflow-hidden whitespace-pre")}>
          {settle && text.startsWith(settle.before + settle.added) ? (
            <>
              <span className="invisible">{settle.before}</span>
              <motion.span
                key={settle.id}
                initial={{ opacity: 1 }}
                animate={{ opacity: 0 }}
                transition={SETTLE}
                className="rounded-sm bg-primary/15 text-transparent"
              >
                {settle.added}
              </motion.span>
            </>
          ) : null}
          {ghost && (
            <>
              <span className="invisible">{text}</span>
              <motion.span
                key={ghost}
                data-ghost=""
                initial={reduceMotion ? { opacity: 0 } : { opacity: 0, x: 4 }}
                animate={{ opacity: 1, x: 0 }}
                transition={APPEAR}
                className="inline-block text-muted-foreground"
              >
                {ghost}
              </motion.span>
            </>
          )}
        </div>
        <input
          ref={input}
          type="text"
          aria-label={label}
          placeholder={placeholder}
          autoComplete="off"
          value={text}
          onChange={(event) => {
            change(event.target.value);
            readCaret();
          }}
          onKeyDown={handleKeyDown}
          onSelect={readCaret}
          onScroll={readCaret}
          className={cn(TEXT, "relative w-full bg-transparent text-foreground outline-none placeholder:text-muted-foreground")}
        />
      </div>
      <div className="flex min-h-8 items-center justify-between gap-3 text-xs text-muted-foreground">
        <button
          type="button"
          role="switch"
          aria-checked={on}
          onClick={toggle}
          className={cn(
            // The button is 2rem tall; the pseudo-element grows the hit area to 2.75rem.
            "relative inline-flex h-8 cursor-pointer touch-manipulation items-center gap-1.5 rounded-md outline-none before:absolute before:-inset-x-2 before:-inset-y-1.5",
            "motion-safe:transition-colors motion-safe:duration-150 hover:text-foreground",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          )}
        >
          <SparkGlyph />
          <span>Suggestions</span>
          <span className="font-medium text-foreground">{on ? "On" : "Off"}</span>
        </button>
        {ghost ? (
          // Not in the Tab order: Tab already accepts from the field. The button serves touch and pointer.
          <button
            type="button"
            tabIndex={-1}
            onClick={accept}
            className="relative inline-flex h-8 cursor-pointer touch-manipulation items-center gap-1.5 rounded-md outline-none before:absolute before:-inset-x-2 before:-inset-y-1.5 hover:text-foreground"
          >
            <kbd className="rounded-md border border-border bg-muted px-1.5 py-0.5 font-sans text-xs text-foreground">Tab</kbd>
            <span>to accept</span>
          </button>
        ) : failed ? (
          <span>No suggestion right now. Keep typing.</span>
        ) : null}
      </div>
      <span role="status" className="sr-only">
        {ghost ? `Suggestion: ${ghost.trim()}. Press Tab to accept, Escape to dismiss.` : failed ? "No suggestion right now." : ""}
      </span>
    </div>
  );
}
